#!/bin/sh
# Set the agent's active voice. Regenerates voice.instructions.md in both rule
# trees from one library file under .github/docs/voices/.
#   sh .github/skills/voice/set-voice.sh <name>     activate a voice
#   sh .github/skills/voice/set-voice.sh --list     list voices with summaries
#   sh .github/skills/voice/set-voice.sh --current  print the active voice
# POSIX sh only. Never commits.
# Also runs from a consuming project root: the sync ships .github/skills/ and .github/docs/voices/.
set -e
cd -P "$(dirname "$0")" && cd ../../..
lib=.github/docs/voices
rule=voice.instructions.md
dsts=".github/instructions/$rule .claude/rules/$rule"

list_voices() {
    for f in "$lib"/*.md; do
        n=$(basename "$f" .md)
        [ "$n" = README ] && continue
        s=$(sed -n 's/^summary: *//p' "$f" | head -1)
        printf '%-10s %s\n' "$n" "$s"
    done
}

case "${1:-}" in
    ''|-h|--help)
        echo "usage: sh .github/skills/voice/set-voice.sh <name> | --list | --current"; list_voices; exit 0 ;;
    --list)
        list_voices; exit 0 ;;
    --current)
        v=$(sed -n 's/^# Voice (active: \(.*\))$/\1/p' ".github/instructions/$rule" 2>/dev/null) || v=
        echo "${v:-none}"; exit 0 ;;
esac

name=$1
src="$lib/$name.md"
if [ ! -f "$src" ] || [ "$name" = README ]; then
    echo "no voice named '$name'. Available:"; list_voices; exit 1
fi

# Body = everything after the closing frontmatter fence.
body=$(awk 'f>=2 {print; next} /^---$/ {f++}' "$src" | sed '/./,$!d')

for dst in $dsts; do
    mkdir -p "$(dirname "$dst")"
    {
        printf -- '---\napplyTo: "**"\n---\n\n'
        printf '# Voice (active: %s)\n\n' "$name"
        printf '> Generated by `.github/skills/voice/set-voice.sh` from `%s`. Do not hand-edit: change the library file and re-run, or swap with `/voice <name>`. Library and contract: `%s/README.md`.\n\n' "$src" "$lib"
        printf 'The active register for every agent response and chat message. It sits on top of the Concise Technical Writing standard in the entry points and never relaxes it: a voice changes tone, never the word budget. Formal records (ADRs, business rules, design docs, plans, system nodes) keep a neutral documentary voice. Scope is human-readable prose, not code comments, structured output, or metadata. Destructive-action confirmations carry no wit in any voice.\n\n'
        printf '%s\n' "$body"
    } > "$dst"
done
echo "voice set to $name ($(sed -n 's/^summary: *//p' "$src" | head -1))"
echo "takes effect in new sessions; in a running one, /voice $name adopts it now"
